(ns payment-orchestrator-clj.provider.asaas.errors (:require [payment-orchestrator-clj.provider.port :as port]))
(defn response-error [{:keys [status body endpoint request-id]}] (let [category (cond (#{400 404} status) :provider.error/invalid-request (#{401 403} status) :provider.error/authentication (= 429 status) :provider.error/rate-limited (<= 500 status 599) :provider.error/unavailable :else :provider.error/unexpected-response) error (first (:errors body))] (port/provider-error category {:provider :asaas :provider-code (:code error) :provider-description (:description error) :provider-http-status status :provider-endpoint endpoint :provider-request-id request-id :retryable? (contains? #{:provider.error/rate-limited :provider.error/unavailable} category) :outcome-known? (not (<= 500 status 599))})))
(defn timeout-error [] (port/provider-error :provider.error/timeout {:provider :asaas :retryable? false :outcome-known? false}))
